<?php
declare(strict_types=1);

session_start();
require_once __DIR__ . '/config/step10_services.php';

if(empty($_SESSION['saved_views_csrf']))$_SESSION['saved_views_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['saved_views_csrf'];
$error=null;$success=null;$ctx=['organization_id'=>0,'club_id'=>0];$views=[];
$targets=[
 'global_search.php'=>'Global Search','members.php'=>'Members & Network','member_profile.php'=>'Member Profile 360°','operations_center.php'=>'Operations Center','insights_center.php'=>'Insights Center','alerts_center.php'=>'Alerts & Follow-ups','report_center.php'=>'Report Center','master_tracking.php'=>'Master Tracking','sp_house.php'=>'SP House','name_wise_tracking.php'=>'Name Wise Tracking','master_business_tracking.php'=>'Master Business Tracking','ums_renewal.php'=>'UMS Renewal','ums_active_duration.php'=>'UMS Active Duration','data_quality.php'=>'Data Quality','audit_center.php'=>'Audit Center','export_center.php'=>'Export Center'
];
try{
 $pdo=business_db();$ctx=step10_org_context($pdo);step10_ensure_tables($pdo);$orgId=(int)$ctx['organization_id'];$clubId=(int)$ctx['club_id'];
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch. Refresh and try again.');
  $action=step10_trim($_POST['action']??'');
  if($action==='save'){
   $name=preg_replace('/\s+/u',' ',step10_trim($_POST['view_name']??''))?:'';$target=step10_trim($_POST['target_page']??'');$query=ltrim(step10_trim($_POST['query_string']??''),'?');
   $len=function_exists('mb_strlen')?mb_strlen($name,'UTF-8'):strlen($name);if($len<2||$len>120)throw new RuntimeException('View name must be 2–120 characters.');if(!isset($targets[$target]))throw new RuntimeException('Target page is not allowed.');if(strlen($query)>1000)throw new RuntimeException('Saved query is too long.');
   if($query!==''&&preg_match('/(?:https?:|javascript:|\\|\.\.)/i',$query))throw new RuntimeException('Saved query contains an unsafe value.');
   $stmt=$pdo->prepare("INSERT INTO business_saved_views(organization_id,user_id,view_name,view_type,target_page,query_string,is_favorite) VALUES (?,NULL,?,'business_workspace',?,?,1)");$stmt->execute([$orgId,$name,$target,$query!==''?$query:null]);$id=(int)$pdo->lastInsertId();step10_audit($pdo,$orgId,$clubId,'business_saved_view_created','business_saved_view',$id,['name'=>$name,'target_page'=>$target,'query_string'=>$query]);$success='Saved view created.';
  }
  if($action==='delete'){$id=isset($_POST['view_id'])&&is_numeric($_POST['view_id'])?(int)$_POST['view_id']:0;$stmt=$pdo->prepare("DELETE FROM business_saved_views WHERE organization_id=? AND id=?");$stmt->execute([$orgId,$id]);if($stmt->rowCount()!==1)throw new RuntimeException('Saved view was not found.');step10_audit($pdo,$orgId,$clubId,'business_saved_view_deleted','business_saved_view',$id,[]);$success='Saved view removed.';}
 }
 $stmt=$pdo->prepare("SELECT * FROM business_saved_views WHERE organization_id=? AND is_favorite=1 ORDER BY updated_at DESC,id DESC");$stmt->execute([$orgId]);$views=$stmt->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
?>
