<div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Business OS</div><nav class="os-nav"><a href="index.php"><i class="dot"></i>Dashboard</a><a href="today_center.php"><i class="dot"></i>Today Center</a><a href="global_search.php"><i class="dot"></i>Global Search</a><a class="active" href="saved_views.php"><i class="dot"></i>Saved Views</a><a href="alerts_center.php"><i class="dot"></i>Alerts</a><a href="insights_center.php"><i class="dot"></i>Insights</a><a href="data_management.php"><i class="dot"></i>Data Management</a></nav><div class="os-sidebar-status"><b>Personal shortcuts</b><span>Save recurring Business OS pages/filters without changing business data.</span></div></aside><main class="os-main">
<section class="os-hero s10-hero"><div class="os-kicker">Step 10V • Saved Views & Favorites</div><h1>Save recurring workspaces instead of rebuilding the same filters every day.</h1><p>A saved view stores only an internal Business OS target page and query string. It does not duplicate or modify business facts.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'SAVED VIEWS LIVE':'Review required' ?></span><span class="os-chip"><?= number_format(count($views)) ?> favorites</span></div></section>
<?php if($success):?><div class="s10-alert good"><?= step10_h($success) ?></div><?php endif;?><?php if($error):?><div class="s10-alert bad"><strong>Saved View diagnostic:</strong> <?= step10_h($error) ?></div><?php else:?>
<section class="s10-grid"><aside class="s10-card s10-span-4"><h2>Save a View</h2><p>Example query: <code>year=2026&amp;month=8</code></p><form class="s10-form-grid" method="post"><input type="hidden" name="csrf" value="<?= step10_h($csrf) ?>"><input type="hidden" name="action" value="save"><div class="s10-field full"><label>Name</label><input name="view_name" maxlength="120" required placeholder="August Operations"></div><div class="s10-field full"><label>Workspace</label><select name="target_page"><?php foreach($targets as $file=>$label):?><option value="<?= step10_h($file) ?>"><?= step10_h($label) ?></option><?php endforeach;?></select></div><div class="s10-field full"><label>Query string (optional)</label><input name="query_string" maxlength="1000" placeholder="year=2026&month=8"></div><div class="s10-field full"><button class="os-btn primary" type="submit">Save Favorite</button></div></form></aside>
<article class="s10-card s10-span-8"><h2>Favorite Workspaces</h2><p>Open a saved internal route with one click.</p><div class="s10-list"><?php if(!$views):?><div class="s10-row"><div><b>No saved views yet</b><small>Create your first recurring workspace shortcut.</small></div></div><?php endif;?><?php foreach($views as $v):$url=(string)$v['target_page'].($v['query_string']?'?'.(string)$v['query_string']:'');?><div class="s10-row"><div><b><?= step10_h($v['view_name']) ?></b><small><?= step10_h($url) ?></small></div><div class="s10-actions"><a class="primary" href="<?= step10_h($url) ?>">Open →</a><form method="post"><input type="hidden" name="csrf" value="<?= step10_h($csrf) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="view_id" value="<?= (int)$v['id'] ?>"><button class="danger" type="submit">Remove</button></form></div></div><?php endforeach;?></div></article></section>
<?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
